#include <bits/stdc++.h>
using namespace std;
const int MAXN = 250005;
int totalN, maxK, modVal;
using LL = long long;

LL fastExponentiation(LL base, LL exponent) {
    LL result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % modVal;
        base = base * base % modVal;
        exponent >>= 1;
    }
    return result;
}

inline int lowbit(int x) {
    return x & -x;
}

LL fact[MAXN], invFact[MAXN], memoDP[26][MAXN];

LL compute(int level, int mask) {
    if (memoDP[level][mask] != -1) return memoDP[level][mask];
    if (mask == 0) {
        memoDP[level][mask] = fact[totalN];
        for (int i = 1; i <= level; i++)
            memoDP[level][mask] = memoDP[level][mask] * (maxK - i + 1) % modVal;
        return memoDP[level][mask];
    }
    LL &res = memoDP[level][mask];
    res = 0;
    int tmp_mask = mask - lowbit(mask);
    for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
        res = (res + invFact[mask - sub_mask] * compute(level + 1, sub_mask)) % modVal;
    res = (res + invFact[mask] * compute(level + 1, 0)) % modVal;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> totalN >> maxK >> modVal;
    LL answer = fastExponentiation(maxK, totalN);
    if (totalN & 1) {
        cout << answer << "\n";
        return 0;
    }
    fact[0] = 1;
    for (int i = 1; i <= totalN; i++) fact[i] = fact[i - 1] * i % modVal;
    invFact[totalN] = fastExponentiation(fact[totalN], modVal - 2);
    for (int i = totalN; i > 0; --i) invFact[i - 1] = invFact[i] * i % modVal;
    memset(memoDP, -1, sizeof(memoDP));
    answer = (answer - compute(0, totalN) + modVal) % modVal;
    cout << answer << "\n";
    return 0;
}
